        local d = 70 + self:rand() * 70
        self:spawn(W, {shape = RECT, x = x + dir * 30, y = y + (self:rand() - 0.5) * 80, w = 30, h = 5, rot = math.deg(ang), col = c, a = 1,
                       to = {x = x + dir * 30 + math.cos(ang) * d, y = y + math.sin(ang) * d, a = 0, sx = 0.3}, dur = 0.18})
