            local b = f >= 1 and (get(f) or 0) or 0
            v = v | ((b & MASK) << (N.BITS * j))
        end
        ints[k + 1] = v
    end
    return ints
end

function N.unpackInputs(list, frameEnd)
    local out = {}
    local first = frameEnd - N.WINDOW + 1
    for k = 0, N.INPUT_INTS - 1 do
        local v = math.tointeger(list[N.F.inputs + k]) or 0
        for j = 0, N.PER_INT - 1 do
