end

local function menuOpts(self, sel, onPick, onBack)
    local app = self.app
    return {x = -app.W / 2 + 380, y = app.H / 2 - 290, w = 560, h = 88, gap = 10, size = 40, sel = sel, numbers = true,
            accent = UI.GOLD, onPick = onPick, onBack = onBack}
