    local app = self.app
    self.menu:free()
    app.input:clearUI()
    self.items = {
        {id = 'vcpu', label = '对战电脑', sub = '自选角色与对手'},
        {id = 'v2p', label = '本地双人', sub = '1P：WASD + J K L I U　2P：方向键 + , . /'},
