        local b = G.bitmap(self.logoG)
        b.node:scale(d.u, d.u)
        cur = {b = b, i = i, img = {bytes = U.decodeAll(tile.d), n = tile.n, pal = self.logoPal,
                                    ax = d.w / 2 - tile.x, ay = d.h / 2}}
