    for _, a in ipairs(actions) do
        if a == 'up' then self.sel = (self.sel - 2) % #self.items + 1; app.audio:play(app.audio.ID.move)
        elseif a == 'down' then self.sel = self.sel % #self.items + 1; app.audio:play(app.audio.ID.move)
